head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05006";
scwin.table_exer_1 = null;
scwin.table_exer_2 = null;
scwin.rownum = 1;
scwin.result = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.table_exer_1 = $c.util.getComponent('table_exer_1');
        scwin.table_exer_2 = $c.util.getComponent('table_exer_2');
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_exerStrtDd();
        scwin.init_datefmt_cal_exerEndDd();
        scwin.init_datefmt_cal_fstExerPrcAdjDd();
        scwin.init_datefmt_cal_exerPrcDd1();
        scwin.init_datefmt_cal_exerPrcReckDd1();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05006.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "ipt_objIsuCd", fn: function () { return String(String((dma_pageContext.get("objIsuCd") ?? ""))); } },
        { childId: "ipt_objIsuNm", fn: function () { return String(String((dma_pageContext.get("objIsuNm") ?? ""))); } },
        { childId: "ipt_stkRelCorpbndExerPrc", fn: function () { return String(String((dma_pageContext.get("stkRelCorpbndExerPrc") ?? ""))); } },
        { childId: "ipt_exerRto", fn: function () { return String(String((dma_pageContext.get("exerRto") ?? ""))); } },
        { childId: "cal_exerStrtDd", fn: function () { return String(String((dma_pageContext.get("exerStrtDd") ?? ""))); } },
        { childId: "cal_exerEndDd", fn: function () { return String(String((dma_pageContext.get("exerEndDd") ?? ""))); } },
        { childId: "ipt_clmInstCd", fn: function () { return String(String((dma_pageContext.get("clmInstCd") ?? ""))); } },
        { childId: "ipt_clmInstNm", fn: function () { return String(String((dma_pageContext.get("clmInstNm") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_exerStrtDd
 * @description 초기화 — datefmt cal exer Strt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_exerStrtDd = function () { $c.date.checkCalendarFormat("cal_exerStrtDd", "yyyyMMdd"); };

