/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.table_exer_1.setStyle("display", "none");
        scwin.table_exer_2.setStyle("display", "none");
        scwin.makeInputFromParent($, {  });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05006.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

