/**
 * @method
 * @name rgt_cd_onChange
 * @description rgt cd on Change 처리
 * @param {*} fm fm
 * @param {*} okvalue okvalue
 * @returns {void}
 * @hidden N
 */
scwin.rgt_cd_onChange = function (fm, okvalue) {
    try {
        if ($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue()=== '40') {
            $c.util.getComponent('slc_proftPartcAccYn').setDisabled(false);
            $c.util.getComponent("slc_proftPartcAccYn").focus();
        } else {
            $c.util.getComponent('slc_proftPartcAccYn').setSelectedIndex(0);
            $c.util.getComponent('slc_proftPartcAccYn').setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldbnf05006.rgt_cd_onChange" });
    }
};

