 * @description obj Isu Cd Onclick 처리
 * @returns {void}
 * @hidden N
 */
scwin.objIsuCdOnclick = function () {
    const fm = (document.InputForm || { elements: [] });
    if ($c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue()=== '10' || $c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue()=== '11' || $c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue()=== '21' || $c.util.getComponent('slc_stkRelCorpbndRghtTpCd').getValue()=== '22') {
        window_sales_cd('objIsuCd', 'objIsuNm', '', $c.util.getComponent("ipt_isurCd").getValue());
    } else {
        window_sales_cd('objIsuCd', 'objIsuNm', '', '');
    }
};

/**
 * @method
 * @name tx_fn_autoCalc
 * @description auto Calc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_autoCalc = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/exer_prc_data.jsp"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/exer_prc_data.jsp", unresolved: "action:../ajax/exer_prc_data.jsp" };
};

