/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function () {

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    $c.util.getComponent("slc_stkRelCorpbndRghtTpCd").setValue(parentfm.stk_rel_corpbnd_rght_tp_cd.value);
    $c.util.getComponent("slc_proftPartcAccYn").setValue(parentfm.proft_partc_acc_yn.value);
    $c.util.getComponent("ipt_objIsuCd").setValue(parentfm.obj_isu_cd.value);
    $c.util.getComponent("ipt_objIsuNm").setValue(parentfm.obj_isu_nm.value);
    $c.util.getComponent("ipt_stkRelCorpbndExerPrc").setValue(parentfm.stk_rel_corpbnd_exer_prc.value);
    $c.util.getComponent("ipt_exerRto").setValue(parentfm.exer_rto.value);
    $c.util.getComponent("cal_exerStrtDd").setValue(parentfm.exer_strt_dd.value);
    $c.util.getComponent("cal_exerEndDd").setValue(parentfm.exer_end_dd.value);
    $c.util.getComponent("ipt_cashPayYn").setValue(parentfm.cash_pay_yn.value);
    $c.util.getComponent("ipt_sbPayYn").setValue(parentfm.sb_pay_yn.value);
    $c.util.getComponent("ipt_clmInstCd").setValue(parentfm.clm_inst_cd.value);
    $c.util.getComponent("ipt_clmInstNm").setValue(parentfm.clm_inst_nm.value);
    $c.util.getComponent("slc_divReckDdTpCd").setValue(parentfm.div_reck_dd_tp_cd.value);
    const v_str1 = parentfm.exer_prc_adj_mktprc_dn_yn.value;
    if (v_str1 === 'N') {
        /* 수동 전환 필요: exer_prc_adj_mktprc_dn_yn[0] 선택 — 옵션표 미해결 */ void 0;
        scwin.showExerHtml('N');
    } else {
        if (v_str1 === 'Y') {
            /* 수동 전환 필요: exer_prc_adj_mktprc_dn_yn[1] 선택 — 옵션표 미해결 */ void 0;
            scwin.showExerHtml('Y');
        }
    }
    $c.util.getComponent("cal_fstExerPrcAdjDd").setValue(parentfm.fst_exer_prc_adj_dd.value);
    const v_str2 = parentfm.stkcert_mmend_tp_cd.value;
    if (v_str2 === '1') {
        /* 수동 전환 필요: stkcert_mmend_tp_cd[0] 선택 — 옵션표 미해결 */ void 0;
    } else {
        if (v_str2 === '2') {
            /* 수동 전환 필요: stkcert_mmend_tp_cd[1] 선택 — 옵션표 미해결 */ void 0;
        }
    }
    $c.util.getComponent("ipt_exerPrcAdjCycle").setValue(parentfm.exer_prc_adj_cycle.value);
    $c.util.getComponent("ipt_exerPrcAdjCnt").setValue(parentfm.exer_prc_adj_cnt.value);
    $("input[name='stk_rel_corpbnd_exer_prc_hanview']").trigger('onkeyup');
