};

// [A] 초기 목록 미해결 — jldbnf05006: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name autoCalcDone
 * @description auto Calc Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.autoCalcDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $(scwin.result.arrList).each(function(i, item) {
            if (i === 0) {
                $c.util.getComponent('cal_exerPrcDd1').setValue(item.day);
                $c.util.getComponent('cal_exerPrcReckDd1').setValue(item.bday);
            } else {
                scwin.addRow();
                $("input[name='exer_prc_dd_" + (i + 1) + "']").val(item.day);
                $("input[name='exer_prc_reck_dd_" + (i + 1) + "']").val(item.bday);
            }
    });
};

/**
 * @method
 * @name autoCalc
 * @description auto Calc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.autoCalc = async function () {
    const r = await scwin.tx_fn_autoCalc();
    try {
        scwin.autoCalcDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf05006.fn_autoCalc' });
    }
    return r;
};
